import {metalAcidTasks,neutralTasks,validSaltAccount} from './acid-models.js?v=20261023-physicscomplete01';
import {showAcids} from './acid-scenes.js?v=20261023-physicscomplete01';
export function mountAcidWidget(l,p,root,{save,done,feedback}){const w=p.widget;w.task??=0;w.answers??={};w.passed??=[];const i=w.task,a=w.answers[i]??={},metal=l.widget==='acids-metals',t=(metal?metalAcidTasks:neutralTasks)[i],kind=metal?'metals':'neutralisation',$=s=>root.querySelector(s);root.innerHTML=`<p><b>Case ${i+1} / 3</b></p><p>${t.reactants}. Salt ions: ${t.ions}. Write the neutral salt formula and predict the other product(s).</p><label class="field-label" for="saltFormula">Salt formula (ASCII or Unicode subscripts)</label><input class="lab-input" id="saltFormula" type="text" autocomplete="off" spellcheck="false"><label class="field-label" for="acidProducts">Other product(s)</label><select class="lab-select" id="acidProducts"><option value="">Choose…</option><option value="hydrogen">Hydrogen</option><option value="water">Water</option><option value="water-co2">Water and carbon dioxide</option><option value="oxygen">Oxygen</option></select><button class="secondary" id="checkAcid">Check my products</button><button class="secondary" id="nextAcid">Next case →</button><p id="acidProgress">${w.passed.length} / 3 cases correct</p>`;$('#saltFormula').value=a.salt||'';$('#acidProducts').value=a.products||'';$('#saltFormula').oninput=e=>{a.salt=e.target.value;save();};$('#acidProducts').onchange=e=>{a.products=e.target.value;save();};showAcids(kind,t,w.passed.includes(i));$('#checkAcid').onclick=()=>{if(!validSaltAccount(t,a.salt||'',a.products||'')){feedback(metal?'Balance the metal-ion charge with chloride or sulfate. Mg/Zn/Fe with these dilute acids give hydrogen; do not use the carbonate or oxide pattern.':'Balance the positive/negative ion charges, keeping polyatomic ions intact with brackets when needed. Oxide/hydroxide gives water; carbonate also gives CO₂.',true);return;}if(!w.passed.includes(i))w.passed.push(i);save();showAcids(kind,t,true);$('#acidProgress').textContent=w.passed.length+' / 3 cases correct';feedback('Correct. The salt formula balances charge and the other products match the reactant family.');if(w.passed.length===3){p.widgetDone=true;save();done();}};$('#nextAcid').onclick=()=>{w.task=(i+1)%3;save();mountAcidWidget(l,p,root,{save,done,feedback});};}
